PRAGMA foreign_keys = ON;
CREATE TABLE source(source_id TEXT PRIMARY KEY, url TEXT NOT NULL, publisher TEXT NOT NULL, document_type TEXT NOT NULL, published_at TEXT, retrieved_at TEXT NOT NULL, content_hash TEXT NOT NULL);
CREATE TABLE company(company_id TEXT PRIMARY KEY, legal_name TEXT NOT NULL, cik TEXT UNIQUE, domicile_country TEXT, incorporation_country TEXT, status TEXT NOT NULL);
CREATE TABLE security(security_id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES company, instrument_type TEXT NOT NULL, share_class TEXT, underlying_security_id TEXT REFERENCES security, adr_ratio TEXT);
CREATE TABLE listing(listing_id TEXT PRIMARY KEY, security_id TEXT NOT NULL REFERENCES security, ticker TEXT NOT NULL, venue TEXT NOT NULL, venue_type TEXT NOT NULL CHECK(venue_type IN ('exchange','otc')), currency TEXT NOT NULL, valid_from TEXT NOT NULL, valid_to TEXT, source_id TEXT NOT NULL REFERENCES source, CHECK(valid_to IS NULL OR valid_to>valid_from));
CREATE UNIQUE INDEX current_listing ON listing(venue,ticker) WHERE valid_to IS NULL;
CREATE TABLE taxonomy_node(scheme TEXT NOT NULL, version TEXT NOT NULL, node_id TEXT NOT NULL, parent_id TEXT, level INTEGER NOT NULL CHECK(level BETWEEN 1 AND 4), label_el TEXT NOT NULL, PRIMARY KEY(scheme,version,node_id), FOREIGN KEY(scheme,version,parent_id) REFERENCES taxonomy_node(scheme,version,node_id), CHECK((level=1 AND parent_id IS NULL) OR (level>1 AND parent_id IS NOT NULL)));
CREATE TABLE classification(classification_id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES company, scheme TEXT NOT NULL, version TEXT NOT NULL, node_id TEXT NOT NULL, is_primary INTEGER NOT NULL CHECK(is_primary IN (0,1)), status TEXT NOT NULL CHECK(status IN ('provisional','verified','superseded')), rationale TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES source, valid_from TEXT NOT NULL, valid_to TEXT, recorded_at TEXT NOT NULL, FOREIGN KEY(scheme,version,node_id) REFERENCES taxonomy_node(scheme,version,node_id), CHECK(valid_to IS NULL OR valid_to>valid_from));
CREATE UNIQUE INDEX current_primary ON classification(company_id,scheme) WHERE is_primary=1 AND valid_to IS NULL AND status!='superseded';
CREATE TABLE segment(segment_id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES company, name TEXT NOT NULL, dimension TEXT NOT NULL CHECK(dimension IN ('business','geography')), period_start TEXT NOT NULL, period_end TEXT NOT NULL, revenue TEXT, currency TEXT, source_id TEXT NOT NULL REFERENCES source);
CREATE TABLE theme(theme_id TEXT PRIMARY KEY, label_el TEXT NOT NULL);
CREATE TABLE company_theme(company_id TEXT NOT NULL REFERENCES company, theme_id TEXT NOT NULL REFERENCES theme, source_id TEXT NOT NULL REFERENCES source, rationale TEXT NOT NULL, valid_from TEXT NOT NULL, valid_to TEXT, PRIMARY KEY(company_id,theme_id,valid_from));
CREATE TABLE metric_observation(observation_id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES company, metric_code TEXT NOT NULL, value TEXT, unit TEXT NOT NULL, currency TEXT, period_start TEXT, period_end TEXT NOT NULL, scope TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES source, recorded_at TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, supersedes_id TEXT REFERENCES metric_observation, missing_reason TEXT, CHECK(value IS NOT NULL OR missing_reason IS NOT NULL));
CREATE TABLE event(event_id TEXT PRIMARY KEY, event_type TEXT NOT NULL, occurred_at TEXT, discovered_at TEXT NOT NULL, title TEXT NOT NULL, summary TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES source, dedup_key TEXT UNIQUE NOT NULL);
CREATE TABLE event_company(event_id TEXT NOT NULL REFERENCES event, company_id TEXT NOT NULL REFERENCES company, relationship TEXT NOT NULL, PRIMARY KEY(event_id,company_id));
CREATE TABLE research_note(note_id TEXT PRIMARY KEY, company_id TEXT REFERENCES company, event_id TEXT REFERENCES event, created_at TEXT NOT NULL, claim TEXT NOT NULL, interpretation TEXT NOT NULL, uncertainty TEXT NOT NULL, supersedes_id TEXT REFERENCES research_note);
CREATE TABLE note_source(note_id TEXT NOT NULL REFERENCES research_note, source_id TEXT NOT NULL REFERENCES source, locator TEXT NOT NULL, PRIMARY KEY(note_id,source_id,locator));
CREATE TABLE market_cap_snapshot(company_id TEXT NOT NULL REFERENCES company, as_of TEXT NOT NULL, market_cap_usd TEXT, method TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES source, PRIMARY KEY(company_id,as_of,source_id));
CREATE TABLE benchmark(benchmark_id TEXT PRIMARY KEY, name TEXT NOT NULL, provider TEXT NOT NULL);
CREATE TABLE membership(benchmark_id TEXT NOT NULL REFERENCES benchmark, security_id TEXT NOT NULL REFERENCES security, valid_from TEXT NOT NULL, valid_to TEXT, source_id TEXT NOT NULL REFERENCES source, PRIMARY KEY(benchmark_id,security_id,valid_from), CHECK(valid_to IS NULL OR valid_to>valid_from));
